def flatten(root):
    node = root
    while node:
        if node.left is not None:
            tail = node.left
            while tail.right is not None:       # last preorder node on the left
                tail = tail.right
            tail.right = node.right             # right subtree follows it
            node.right, node.left = node.left, None
        node = node.right
